// File-management ops for the Library tab: fetch + save remote
// images, save user-generated bytes, list / delete entries on disk,
// and the WebP thumbnail cache that backs the grid. The shell exposes
// these 1:1 as Tauri commands (src-tauri/src/commands.rs).

use std::hash::{Hash, Hasher};
use std::path::{Path, PathBuf};

/// The directory new wallpapers are written to — the OS/DE-conventional
/// wallpaper location, namespaced under an `Ambient/` subfolder so we
/// only ever manage our own files and the native wallpaper pickers can
/// browse to them:
///   - KDE Plasma → ~/.local/share/wallpapers/Ambient (the KDE picker
///     scans this tree)
///   - everywhere else (GNOME/other Linux, macOS, Windows) →
///     <Pictures>/Ambient
/// Falls back to <app_data>/wallpapers if neither resolves.
pub(crate) fn wallpaper_dir() -> Result<PathBuf, String> {
    #[cfg(target_os = "linux")]
    {
        let de = std::env::var("XDG_CURRENT_DESKTOP")
            .unwrap_or_default()
            .to_lowercase();
        if de.contains("kde") || de.contains("plasma") {
            if let Ok(home) = std::env::var("HOME") {
                return Ok(PathBuf::from(home).join(".local/share/wallpapers/Ambient"));
            }
        }
    }
    // XDG/known-folder Pictures lookup — the same dirs Tauri's
    // app.path().picture_dir() resolved pre-extraction.
    if let Some(pics) =
        directories::UserDirs::new().and_then(|u| u.picture_dir().map(Path::to_path_buf))
    {
        return Ok(pics.join("Ambient"));
    }
    Ok(crate::state::data_dir().join("wallpapers"))
}

/// Download a URL and save it into the OS wallpaper directory (see
/// `wallpaper_dir`), returning the resolved absolute path. Internal
/// helper for the Rust-side fetch pipelines in `sources.rs` / `aigen.rs`.
pub(crate) async fn download_and_save(url: &str, filename: &str) -> Result<String, String> {
    let res = reqwest::get(url)
        .await
        .map_err(|e| format!("download request to {}: {}", url, e))?;
    if !res.status().is_success() {
        return Err(format!("download {}: HTTP {}", url, res.status()));
    }
    let bytes = res
        .bytes()
        .await
        .map_err(|e| format!("read response bytes from {}: {}", url, e))?;

    save_image_bytes(&bytes, filename)
}

/// Write already-downloaded image bytes into the wallpaper dir, returning
/// the resolved absolute path. Shared by `download_and_save` and callers
/// that fetch the bytes themselves (aigen.rs does so to attach a Referer
/// header and parse provider-specific error bodies).
pub(crate) fn save_image_bytes(bytes: &[u8], filename: &str) -> Result<String, String> {
    let target = wallpaper_target(filename)?;
    std::fs::write(&target, bytes)
        .map_err(|e| format!("write wallpaper to {:?}: {}", target, e))?;

    target
        .to_str()
        .map(String::from)
        .ok_or_else(|| "saved wallpaper path is not valid UTF-8".into())
}

pub async fn list_wallpapers() -> Result<Vec<String>, String> {
    // Scan the current OS wallpaper dir AND the legacy <app_data>/wallpapers
    // location, so a library saved before wallpapers moved to the OS dir
    // isn't orphan-swept on upgrade.
    let mut dirs = vec![wallpaper_dir()?];
    let legacy = crate::state::data_dir().join("wallpapers");
    if !dirs.contains(&legacy) {
        dirs.push(legacy);
    }
    // Directory scans are blocking fs IO — run them off the async
    // workers, mirroring get_or_create_thumbnail.
    tokio::task::spawn_blocking(move || {
        let mut out = Vec::new();
        for dir in dirs {
            let Ok(rd) = std::fs::read_dir(&dir) else {
                continue;
            };
            for entry in rd.flatten() {
                // Skip the thumbs subdir / any nested dir — only image files.
                if entry.path().is_dir() {
                    continue;
                }
                if let Some(s) = entry.path().to_str() {
                    out.push(s.to_string());
                }
            }
        }
        Ok(out)
    })
    .await
    .map_err(|e| e.to_string())?
}

pub async fn delete_wallpaper(path: String) -> Result<(), String> {
    // Blocking fs IO off the async workers (see get_or_create_thumbnail).
    tokio::task::spawn_blocking(move || -> Result<(), String> {
        std::fs::remove_file(&path).map_err(|e| e.to_string())?;
        // Best-effort thumb cleanup. Failure is non-fatal (the thumb may
        // never have been generated, or the dir might be missing); we don't
        // want a missing thumb to block the user's delete intent.
        let _ = remove_thumbnail_for(&path);
        Ok(())
    })
    .await
    .map_err(|e| e.to_string())?
}

/// All directories Ambient may have written wallpapers to (current OS dir
/// + legacy app-data location), for the bulk delete / scan paths.
fn all_wallpaper_dirs() -> Vec<PathBuf> {
    let mut dirs = match wallpaper_dir() {
        Ok(d) => vec![d],
        Err(_) => Vec::new(),
    };
    let legacy = crate::state::data_dir().join("wallpapers");
    if !dirs.contains(&legacy) {
        dirs.push(legacy);
    }
    dirs
}

/// Remove the whole WebP thumbnail cache (<app_data>/thumbs). Cheap,
/// regenerable on demand — backs the Settings "Clear cache" action.
fn clear_thumbs() -> Result<(), String> {
    let thumbs = crate::state::data_dir().join("thumbs");
    if thumbs.exists() {
        std::fs::remove_dir_all(&thumbs).map_err(|e| format!("clear thumbs: {e}"))?;
    }
    Ok(())
}

/// Settings → "Clear cache": drop the regenerable thumbnail cache. The
/// grid re-creates thumbnails lazily on next view, so this is safe and
/// non-destructive to actual wallpapers.
pub async fn clear_thumbnail_cache() -> Result<(), String> {
    clear_thumbs()
}

/// Settings → "Delete saved wallpapers": remove every wallpaper file
/// Ambient has saved (both the current OS dir and the legacy location),
/// wipe the thumbnail cache, and empty the library index. Returns how
/// many image files were deleted. The currently-applied desktop wallpaper
/// is the DE's own copy/reference, so the live desktop is unaffected.
pub async fn delete_local_wallpapers() -> Result<u32, String> {
    // The scan + per-file deletes are blocking fs IO — run them off the
    // async workers, mirroring get_or_create_thumbnail.
    let removed = tokio::task::spawn_blocking(|| {
        let mut removed = 0u32;
        for dir in all_wallpaper_dirs() {
            let Ok(rd) = std::fs::read_dir(&dir) else {
                continue;
            };
            for entry in rd.flatten() {
                let p = entry.path();
                if p.is_dir() {
                    continue; // skip any nested dir (e.g. a stray thumbs/)
                }
                if std::fs::remove_file(&p).is_ok() {
                    removed += 1;
                }
            }
        }
        // Thumbnails point at now-deleted files — clear them too.
        let _ = clear_thumbs();
        removed
    })
    .await
    .map_err(|e| e.to_string())?;
    // Empty the index so the Library tab reflects the deletion immediately
    // (patch emits `library-changed`).
    let _ = crate::state::library()
        .patch(crate::library_store::LibraryOp::Clear)
        .await;
    Ok(removed)
}

pub async fn get_or_create_thumbnail(path: String) -> Result<String, String> {
    let src = PathBuf::from(&path);
    if !src.exists() {
        return Err(format!("source missing: {}", path));
    }
    let thumb_path = thumbnail_path_for(&src)
        .ok_or_else(|| format!("could not derive thumb path for: {}", path))?;

    // Cache hit. mtime check defends against the rare case of a source
    // being overwritten at the same path (rotation re-fetch from the
    // same URL could in theory replace bytes), though Library paths
    // are typically immutable.
    if let (Ok(s_meta), Ok(t_meta)) = (src.metadata(), thumb_path.metadata()) {
        if let (Ok(s_modified), Ok(t_modified)) = (s_meta.modified(), t_meta.modified()) {
            if t_modified >= s_modified {
                return Ok(thumb_path.to_string_lossy().into_owned());
            }
        }
    }

    let thumbs_dir = thumb_path
        .parent()
        .ok_or_else(|| "no thumbs dir parent".to_string())?
        .to_path_buf();
    std::fs::create_dir_all(&thumbs_dir).map_err(|e| e.to_string())?;

    // image::open + thumbnail are CPU-bound; route through
    // spawn_blocking so a 1080p+ decode doesn't park the worker
    // thread serving UI invokes. 480×300 keeps the 16:10 ratio of the
    // Library card; aspect mismatch (e.g. NASA 1:1 shots) is handled
    // by CSS object-fit on the <img> tag.
    let src_clone = src.clone();
    let thumb_clone = thumb_path.clone();
    tokio::task::spawn_blocking(move || -> Result<String, String> {
        let img = image::open(&src_clone).map_err(|e| format!("decode {:?}: {}", src_clone, e))?;
        let thumb = img.thumbnail(480, 300);
        thumb
            .save(&thumb_clone)
            .map_err(|e| format!("encode {:?}: {}", thumb_clone, e))?;
        Ok(thumb_clone.to_string_lossy().into_owned())
    })
    .await
    .map_err(|e| e.to_string())?
}

/// Thumbnails live under <app_data>/thumbs/<hash>.webp — keyed by a hash
/// of the wallpaper's absolute path, NOT as a sibling of the wallpaper.
/// That keeps the app's cache out of the user's Pictures / the KDE
/// wallpaper dir (where a stray `thumbs/` folder would clutter the
/// picker), and stays app-managed.
pub(crate) fn thumbnail_path_for(src: &Path) -> Option<PathBuf> {
    let thumbs = crate::state::data_dir().join("thumbs");
    let mut h = std::collections::hash_map::DefaultHasher::new();
    src.to_string_lossy().hash(&mut h);
    Some(thumbs.join(format!("{:016x}.webp", h.finish())))
}

fn remove_thumbnail_for(path: &str) -> std::io::Result<()> {
    let Some(thumb) = thumbnail_path_for(&PathBuf::from(path)) else {
        return Ok(());
    };
    if !thumb.exists() {
        return Ok(());
    }
    std::fs::remove_file(&thumb)
}

fn wallpaper_target(filename: &str) -> Result<PathBuf, String> {
    let wallpapers = wallpaper_dir()?;
    std::fs::create_dir_all(&wallpapers)
        .map_err(|e| format!("create wallpapers dir {:?}: {}", wallpapers, e))?;
    Ok(wallpapers.join(safe_filename(filename)))
}

pub(crate) fn safe_filename(name: &str) -> String {
    name.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '.' || c == '-' || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn safe_filename_preserves_alphanumerics_and_dots() {
        assert_eq!(safe_filename("Ambient_0.3.0.dmg"), "Ambient_0.3.0.dmg");
        assert_eq!(safe_filename("foo-bar.png"), "foo-bar.png");
    }

    #[test]
    fn safe_filename_replaces_path_separators() {
        assert_eq!(safe_filename("/etc/passwd"), "_etc_passwd");
        assert_eq!(safe_filename("..\\..\\evil"), ".._.._evil");
    }

    #[test]
    fn safe_filename_replaces_spaces_and_unicode() {
        assert_eq!(safe_filename("hello world.png"), "hello_world.png");
        // Non-ASCII alphanumerics collapse to '_' per char-iteration —
        // a single accented codepoint becomes a single underscore.
        assert_eq!(safe_filename("café.png"), "caf_.png");
    }

    #[test]
    fn thumbnail_hash_is_stable_and_path_specific() {
        // The thumb filename is a stable hash of the source path string —
        // same path → same name, different path → different name. (Full
        // path resolution needs the initialized data dir, so we test the
        // hashing invariant directly.)
        use std::collections::hash_map::DefaultHasher;
        let h = |s: &str| {
            let mut hasher = DefaultHasher::new();
            s.hash(&mut hasher);
            hasher.finish()
        };
        assert_eq!(h("/a/b/foo.png"), h("/a/b/foo.png"));
        assert_ne!(h("/a/b/foo.png"), h("/a/b/bar.png"));
    }
}
